export const S3K_API_MD: string = "# s3k kit API (generated by `npm run s3k:api` from api.d.ts: do not edit by hand)\nWrite one scene file that imports ONLY from \"s3k\" and \"three\" (plus react and remotion basics). Units: metres, seconds, degrees; y is up; the cut face is the plane z = 0 and the viewer is on +z.\n\n## Rules (each one prevents a look that was rejected)\n1. Order inside <Stage>: <World/> first, then your objects, <CameraRig/>, and <Finish/> LAST.\n2. Nothing floats: place every object with rest(object, plane) (or models.get(...) which already stands on y = 0). Never guess a y. Only an idea scene (data structure, algorithm, network) may hang its parts in the air above a \"studio\" ground (example D).\n3. All motion is a pure function of t from useT(): build once in useMemo, then call part.update(t) each render. No Math.random (use rnd(seed)), no state between frames, no Date, no timers.\n4. Build in useMemo keyed by [models]; never create meshes, textures or materials per frame. Repeating things use instance(); keep draw calls low.\n5. Frame the focus, not the world: portrait is narrow and TALL. A shot should fill 0.5..1 of the safe area (coverage.fill); use { frame: { box } } shots and check onReport. Lay the subject out to fill the tall frame (never a long thin row), and change angle and distance between shots.\n6. Camera never below ground or water: pass floor to CameraRig. Keep the sun's focus box tight (World focus) so shadows stay crisp.\n7. Strata and ground textures are world-aligned (a pebble has one size everywhere); tile = metres per texture tile.\n8. Captions: <=32 characters, one per shot, through Stage overlay={<Captions items={...}/>}.\n9. Models come from catalogue ids through useModels(ids, resolver); render nothing until it returns non-null.\n10. Copy from the examples (below): they are plain readable code, not magic.\n\n## Skeleton\n```tsx\nconst models = useModels(IDS, resolver);            // inside the canvas, in a component\nconst parts = useMemo(() => models && build(models), [models]);   // build once\nparts.update(useT());                                // every render\n<Stage overlay={<Captions items={CAPS} />}>\n  <World focus={BOX} ground={{ y: 0, zMax: 0 }} sea={{ y: -29, zMin: 0 }} />\n  <CutawayBox x0={-420} x1={420} bottom={-70} holes={[HOLE]} />\n  <primitive object={parts.root} />\n  <CameraRig shots={SHOTS} floor={1.5} />\n  <Finish />\n</Stage>\n```\n\n## Presets\n- haze: fogDensity 0.0034, sun 3.3 at 43.3 deg elevation, exposure 1.05, fog #d6e6ee\n- clear: fogDensity 0.0024, sun 3.6 at 48 deg elevation, exposure 1, fog #dcebf3\n- dusk: fogDensity 0.0036, sun 2.8 at 12 deg elevation, exposure 1.1, fog #e9b08e\n- overcast: fogDensity 0.0042, sun 1.3 at 55 deg elevation, exposure 1.05, fog #d3d9dc\n- studio: fogDensity 0.004, sun 2.4 at 50 deg elevation, exposure 1.1, fog #1c2640\nLimits: fogDensity 0..0.02, sunIntensity 0..10, sunElevationDeg 2..89, exposure 0.3..3.\n\n## Types\n```ts\ntype V3 = [number, number, number];\ntype Box = { min: V3; max: V3 };\ntype Slot = { x: number; y: number; z: number; rx?: number; ry?: number; rz?: number; s?: number };\ntype Layer = { color: string; h: number; pebbles?: boolean | { count?: number; rmin?: number; rmax?: number } };\ntype RigShot = { t: number; at: V3; look: V3 } | { t: number; frame: { box: Box; yawDeg: number; pitchDeg: number; distanceMul?: number } };\ntype Coverage = { fits: boolean; width: number; height: number; fill: number };\ntype Safe = { top: number; bottom: number; left: number; right: number };\ntype PresetName = \"clear\" | \"haze\" | \"dusk\" | \"overcast\" | \"studio\";\ntype WorldPreset = { top: string; mid: string; horizon: string; fog: string; fogDensity: number; sun: string; sunIntensity: number; sunAzimuthDeg: number; sunElevationDeg: number; glow: number; hemiSky: string; hemiGround: string; hemiK: number; bounce: string; exposure: number };\ntype ModelResolver = { resolve(ref: { catalog: string } | { file: string }): { url: string } | null };\ntype FitOptions = { size?: number; height?: boolean; info?: { default_scale?: number; pivot?: \"bottom\" | \"center\" }; matte?: boolean };\ntype Models = { has(id: string): boolean; get(id: string, o?: FitOptions): THREE.Group };\ntype Seed = { a: number; r: number; p: number; sp: number; v: number };\ntype Plane = number | { y: number } | ((x: number, z: number) => number);\n```\n\n## Scene skeleton\n```ts\n/** One story beat with its REAL time in the narration (seconds). */\nexport type SceneBeat = { id: string; text: string; from: number; to: number };\n/** The props of the default-exported scene component of an AI-written scene. The host draws Stage, the captions and the sound: your scene returns only the 3D content (World ... Finish). */\nexport type SceneProps = { resolver: ModelResolver; beats: readonly SceneBeat[]; durationS: number };\n/** THE PAGE: wraps your 3D content in the canvas (ACES, soft shadows) and gives useT(); `overlay` is HTML drawn over it (Captions). Children: World, objects, CameraRig, Finish LAST. */\nexport const Stage: FC<{ children: ReactNode; overlay?: ReactNode; background?: string }>;\n/** Seconds since the start of the video. Call it once per component and pass t to every update(t); motion must be a pure function of t. */\nexport function useT(): number;\n/** Same object while its JSON is unchanged: wrap inline object props so they do not rebuild the scene every frame. */\nexport function useStable<T>(value: T): T;\n/** React context behind useT (Stage provides it; you never need it). */\nexport const TimeContext: Context<number>;\n```\n\n## World (sky, haze, sun, light, ground, sea)\n```ts\n/** Sky gradient, exp haze, sun with soft shadows fitted to `focus`, environment light baked once. ground/sea planes reach the horizon; z ranges clip them (zMax: 0 = only behind a cut at z = 0). */\nexport const World: FC<{ focus: Box; preset?: PresetName; tweak?: Partial<WorldPreset>; ground?: { y?: number; kind?: \"pave\" | \"sand\" | \"plain\"; tile?: number; color?: string; zMin?: number; zMax?: number } | false; sea?: { y: number; color?: string; zMin?: number; zMax?: number; foamZ?: number } | false; shadowSize?: 2048 | 4096 }>;\n/** Preset values merged with tweak; throws a clear message when out of range (fogDensity 0..0.02, sunIntensity 0..10, sunElevationDeg 2..89, exposure 0.3..3). */\nexport function resolvePreset(name?: PresetName, tweak?: Partial<WorldPreset>): WorldPreset;\n/** The four looks: haze (default, approved), clear, dusk, overcast. */\nexport const WORLD_PRESETS: Record<PresetName, WorldPreset>;\n/** [\"clear\", \"haze\", \"dusk\", \"overcast\"]. */\nexport const PRESET_NAMES: readonly PresetName[];\n/** Allowed ranges of the preset numbers. */\nexport const PRESET_LIMITS: Readonly<Record<string, readonly [number, number]>>;\n/** Problems found in a preset (empty = valid). */\nexport function presetProblems(p: WorldPreset): string[];\n/** Shadow camera that covers exactly box b for a sun towards dir; casterReach pulls near back so tall things outside still shadow. */\nexport function fitSunFrustum(b: Box, dir: V3, margin?: number, casterReach?: number): { target: V3; position: V3; left: number; right: number; top: number; bottom: number; near: number; far: number };\n/** Unit vector towards the sun (azimuth 0 = +z, 90 = +x). */\nexport function sunVector(azimuthDeg: number, elevationDeg: number): V3;\n/** THE RULE: put the lowest point of object on the plane (a height, {y} or fn(x,z)), plus lift (0.03 stops z-fighting). Never place by a guessed y. */\nexport function rest<T extends THREE.Object3D>(object: T, plane: Plane, lift?: number): T;\n/** rest() on uneven ground given as a function of x, z. */\nexport function groundSnap<T extends THREE.Object3D>(object: T, ground: (x: number, z: number) => number, lift?: number): T;\n/** Lowest world y of an object. */\nexport function lowestY(object: THREE.Object3D): number;\n/** Height change that puts minY on planeY (+lift). */\nexport function restOffset(minY: number, planeY: number, lift?: number): number;\n/** Names of items whose lowest point is more than tol (0.05) from their plane: a floating check. */\nexport function floaters(items: readonly { name: string; minY: number; planeY: number }[], tol?: number): string[];\n```\n\n## Cutaway ground\n```ts\n/** Cut face of earth at plane z (default 0, viewer on +z): layers (strata, tilt up to 25 deg), holes punched out, parapet, a sea strip in front, a glass-front water block behind. */\nexport const CutawayBox: FC<{ x0: number; x1: number; bottom: number; top?: number; holes?: [number, number][][]; layers?: readonly Layer[]; tiltDeg?: number; tile?: number; z?: number; parapet?: boolean | { height?: number; color?: string }; seaStrip?: { y: number; depth?: number; color?: string }; waterBlock?: { x0: number; x1: number; y0: number; y1: number; depth?: number } }>;\n/** Face geometry (rectangle with holes, world-aligned UVs). */\nexport function buildCutFace(p: { x0: number; x1: number; top?: number; bottom: number; holes?: [number, number][][]; tile?: number; tiltDeg?: number }): THREE.ShapeGeometry;\n/** World-aligned strata UV for a point: one tile = `tile` metres, tilt shears the layers. */\nexport function strataUV(x: number, y: number, tile: number, tiltDeg: number, top?: number): [number, number];\n/** Maximum layer tilt in degrees (25). */\nexport const TILT_LIMIT_DEG: number;\n/** Default soil layers, top to bottom (sand with dense pebbles, clay, gravel...). pebbles: true | { count, rmin, rmax }. */\nexport const STRATA_DEFAULT: readonly Layer[];\n/** Lower edge of each layer as a 0..1 fraction of the tile (top 0). */\nexport function layerEdges(layers: readonly Layer[]): number[];\n```\n\n## Finish chain\n```ts\n/** LAST child of Stage: GTAO, depth of field that follows focus (a [x,y,z] point, a distance, or the rig target), bloom, vignette, tone map; MSAA half-float. mode \"fast\" = no AO/DOF. */\nexport const Finish: FC<{ focus?: V3 | number; mode?: \"full\" | \"fast\"; ao?: boolean; dof?: number; bloom?: number; vignette?: number; saturation?: number }>;\n/** Clamps every Finish knob into its limit and applies mode. */\nexport function resolveFinish(p: { mode?: \"full\" | \"fast\"; ao?: boolean; dof?: number; bloom?: number; vignette?: number; saturation?: number }): { ao: boolean; dof: number; bloom: number; vignette: number; saturation: number; samples: number };\n/** Defaults: bloom 0.32, vignette 0.42, saturation 1.08, dof 1. */\nexport const FINISH_DEFAULTS: Readonly<Record<string, number>>;\n/** Limits: dof 0..3, bloom 0..1.5, vignette 0..0.8, saturation 0.5..1.5. */\nexport const FINISH_LIMITS: Readonly<Record<string, readonly [number, number]>>;\n```\n\n## Camera rig and captions\n```ts\n/** One glide through shot keys (monotone spline, rest at both ends). Shots: { t, at, look } or { t, frame: { box, yawDeg, pitchDeg } } fitted into the portrait safe area. floor keeps the eye above ground/water. hero leans look-at to a moving object. Needs 2+ shots, increasing t. */\nexport const CameraRig: FC<{ shots: readonly RigShot[]; floor?: number | ((x: number, z: number) => number); hero?: { at: (t: number) => V3; from: number; to: number; strength?: number; fade?: number }; safe?: Safe; fov?: number; onReport?: (r: { index: number; fill: number; fits: boolean }[]) => void }>;\n/** Wrap the ONE hero (the thing the story is about) in <Hero>...</Hero>; it changes nothing on screen. The app measures it in the preview pictures: it must be declared, 25 to 60 percent of the frame width, and never cut off by the frame. */\nexport const Hero: FC<{ children: ReactNode }>;\n/** Nearest camera along yaw/pitch that fits the box in the safe area, never below minY; returns position, target, coverage, pitch. */\nexport function frameFocus(i: { box: Box; yawDeg: number; pitchDeg: number; aspect: number; safe?: Safe; fovDeg?: number; minY?: number; distanceMul?: number }): { position: V3; target: V3; coverage: Coverage; pitchDeg: number };\n/** How much of the safe area a box covers from a camera: fits, width, height, fill (aim 0.7..1 hero, 0.3..0.6 establishing). */\nexport function coverage(box: Box, eye: V3, target: V3, aspect: number, safe?: Safe, fovDeg?: number): Coverage;\n/** n key times over duration that give the proof's gentle start and end. */\nexport function glideTimes(n: number, duration: number): number[];\n/** Shots -> spline keys for an aspect ratio. */\nexport function resolveShots(shots: readonly RigShot[], aspect: number, opt?: { safe?: Safe; minY?: number; fovDeg?: number }): { key: { t: number; position: V3; target: V3 }; coverage: Coverage | null }[];\n/** Camera pose at t from keys, above floor, hero lock applied. */\nexport function rigPose(keys: readonly { t: number; position: V3; target: V3 }[], t: number, floor?: number | ((x: number, z: number) => number), hero?: { at: (t: number) => V3; from: number; to: number; strength?: number; fade?: number }): { position: V3; target: V3 };\n/** Hero lock weight 0..1 at t (eases in and out). */\nexport function heroWeight(t: number, h: { from: number; to: number; strength?: number; fade?: number }): number;\n/** Vertical field of view used everywhere (40). */\nexport const FOV_DEG: number;\n/** Safe area for 9:16: top 0.24 (caption), bottom 0.10, sides 0.06. */\nexport const SAFE_PORTRAIT: Safe;\n/** Safe area for 16:9. */\nexport const SAFE_WIDE: Safe;\n/** Safe area for an aspect ratio. */\nexport function safeFor(aspect: number): Safe;\n/** Caption pill (white bold on dark rounded) for the current time; sibling AFTER the canvas via Stage overlay. Keep texts under ~32 characters. */\nexport const Captions: FC<{ items: readonly { from: number; to: number; text: string }[]; top?: number; size?: number }>;\n/** Opacity k/alpha of a caption at t (ease in 0.35 s, out 0.3 s). */\nexport function captionPhase(t: number, from: number, to: number): { active: boolean; k: number; alpha: number };\n/** 3D measuring line with end ticks and a label that faces the camera. */\nexport const Ruler: FC<{ from: V3; to: V3; label: string; color?: string; width?: number; labelSize?: number }>;\n/** A text tag in the scene (white on a dark pill, faces the camera, drawn on top), size = height in metres: name the parts (head, next, null). */\nexport function label(text: string, o?: { size?: number; color?: string; background?: string }): THREE.Sprite;\n```\n\n## Models, instancing, particles\n```ts\n/** Loads catalogue ids through resolver, holds the render until drawn once. Returns null while loading: render nothing until it is set. Missing models become grey boxes. */\nexport function useModels(ids: readonly string[], resolver: ModelResolver, info?: (id: string) => { default_scale?: number; pivot?: \"bottom\" | \"center\" } | undefined): Models | null;\n/** models.get(id, { size, height }) = clone with base on y 0, centred on x/z, longest side (or height) = size metres; no size = manifest default_scale. */\nexport function fitModel(source: THREE.Object3D, o?: FitOptions): THREE.Group;\n/** Scale that makes dims meet the FitOptions. */\nexport function fitScale(dims: { x: number; y: number; z: number }, o: FitOptions): number;\n/** Resolver from a function id -> url (in a render: staticFile(\"assets3d/files/<id>.glb\")). */\nexport function idResolver(urlFor: (id: string) => string): ModelResolver;\n/** Hold the render yourself for your own async set-up; call the returned function once when done. */\nexport function useHold(label: string): () => void;\n/** InstancedMesh with one copy per slot (one draw call); tint(i) gives a colour per copy. */\nexport function instance(geo: THREE.BufferGeometry, mat: THREE.Material, slots: readonly Slot[], o?: { tint?: (i: number) => THREE.ColorRepresentation; shadows?: boolean }): THREE.InstancedMesh;\n/** Rewrites an InstancedMesh's matrices from slots (move them in update). */\nexport function placeSlots(im: THREE.InstancedMesh, slots: readonly Slot[]): void;\n/** count slots in a straight row: start + step * i. */\nexport function rowSlots(count: number, start: V3, step: V3): Slot[];\n/** count slots on a circle in the plane perpendicular to axis x|y|z, each rotated outward. */\nexport function ringSlots(count: number, radius: number, axis?: \"x\" | \"y\" | \"z\", c?: V3, startDeg?: number): Slot[];\n/** cols x rows grid on a wall facing z or x (windows, panels), cells dx by dy apart, centred on c. */\nexport function gridSlots(cols: number, rows: number, dx: number, dy: number, c?: V3, axis?: \"z\" | \"x\"): Slot[];\n/** CPU-updated Points for dust, spray, smoke: emit(seed, phase 0..1, t, out, i) writes each position; call update(t) every frame, add points to the scene. */\nexport function makeParticles(o: { count: number; seed?: number; size?: number; color?: string; opacity?: number; emit: (s: Seed, ph: number, t: number, out: V3, i: number) => void }): { points: THREE.Points; update: (t: number) => void };\n/** Per-particle fixed random numbers a, r, p, sp, v (0..1, sp 0.12..0.42). */\nexport function particleSeeds(count: number, seed?: number): Seed[];\n/** Looping phase 0..1 of a particle at t. */\nexport function phaseOf(t: number, s: { p: number; sp: number }): number;\n```\n\n## Parts, textures, city, maths\n```ts\n/** Standard material (rough .55, metal .1, env .5). */\nexport function std(color: string | number, o?: Partial<THREE.MeshStandardMaterialParameters>): THREE.MeshStandardMaterial;\n/** Painted steel material. */\nexport function steel(c: string | number, rough?: number): THREE.MeshStandardMaterial;\n/** Emissive lamp material (bloom picks it up). */\nexport function glow(c: string, k?: number): THREE.MeshStandardMaterial;\n/** Env light factor baked into std (0.5). */\nexport const ENV_K: number;\n/** Cast/receive shadows on a whole tree. */\nexport function shadowize<T extends THREE.Object3D>(o: T, cast?: boolean, recv?: boolean): T;\n/** Box w,h,d centred at x,y,z; added to parent when given. */\nexport function box(w: number, h: number, d: number, mat: THREE.Material, x: number, y: number, z: number, parent?: THREE.Object3D): THREE.Mesh;\n/** Cylinder along axis x|y|z centred at x,y,z. */\nexport function cyl(rt: number, rb: number, len: number, mat: THREE.Material, axis: \"x\" | \"y\" | \"z\", x: number, y: number, z: number, parent?: THREE.Object3D, seg?: number): THREE.Mesh;\n/** Strut of radius r from a to b. */\nexport function between(a: THREE.Vector3, b: THREE.Vector3, r: number, mat: THREE.Material, parent?: THREE.Object3D, seg?: number): THREE.Mesh;\n/** Arrow from a to b (shaft of radius r, cone head ending at b): use it for any direction, flow or \"points to\" link. */\nexport function arrow(a: THREE.Vector3, b: THREE.Vector3, r: number, mat: THREE.Material, parent?: THREE.Object3D): THREE.Group;\n/** Wedge of a ring around the x axis (half pipe, tunnel wall): outer/inner radius, angles in radians, length along +x. */\nexport function sector(rO: number, rI: number, a0: number, a1: number, len: number): THREE.ExtrudeGeometry;\n/** Full ring around the x axis. */\nexport function ring(rO: number, rI: number, len: number): THREE.ExtrudeGeometry;\n/** Seeded random 0..1 generator: the only allowed randomness (frames must repeat). */\nexport function rnd(seed: number): () => number;\n/** Clamp x into lo..hi (default 0..1). */\nexport function clamp(x: number, lo?: number, hi?: number): number;\n/** Linear blend a to b by u. */\nexport function lerp(a: number, b: number, u: number): number;\n/** Smootherstep of x clamped 0..1. */\nexport function smooth(x: number): number;\n/** Progress of t through [a, b] clamped 0..1: ramp(t, 4, 6). */\nexport function ramp(t: number, a: number, b: number): number;\n/** Canvas -> sRGB texture (rep = RepeatWrapping repeats). Textures are cached; clone before changing repeat. */\nexport function toTexture(c: HTMLCanvasElement, rep?: [number, number]): THREE.CanvasTexture;\n/** Layered ground tile (tiles seamlessly across x). */\nexport function strataTexture(layers?: readonly Layer[], seed?: number): THREE.CanvasTexture;\n/** River stones tile. */\nexport function pebbleTexture(rep?: [number, number]): THREE.CanvasTexture;\n/** Sand with ripples. */\nexport function sandTexture(base?: string): THREE.CanvasTexture;\n/** Water bump map. */\nexport function rippleTexture(): THREE.CanvasTexture;\n/** Paving slabs. */\nexport function paveTexture(base?: string): THREE.CanvasTexture;\n/** Road asphalt with lane lines (tile 16 m x 7.5 m). */\nexport function asphaltTexture(): THREE.CanvasTexture;\n/** Poured concrete with joints; band = coloured stripe. */\nexport function concreteTexture(base?: string, band?: string): THREE.CanvasTexture;\n/** Conveyor cleats; scroll with offset.x. */\nexport function beltTexture(): THREE.CanvasTexture;\n/** Sign text on a flat colour (use MeshBasicMaterial toneMapped:false). */\nexport function signTexture(text: string, bg?: string, fg?: string): THREE.CanvasTexture;\n/** Soft round dot for particles. */\nexport function dustSprite(): THREE.CanvasTexture;\n/** Water-behind-glass colour ramp. */\nexport function glassWaterTexture(): THREE.CanvasTexture;\n/** Glass facade tile, kind 0..4. */\nexport function facadeTexture(kind: number): THREE.CanvasTexture;\n/** Box whose UVs are in metres: windows keep their size on any tower. */\nexport function tower(w: number, h: number, d: number): THREE.BoxGeometry;\n/** Five facade materials (far = flat). */\nexport function towerMaterials(far?: boolean): THREE.MeshStandardMaterial[];\n/** Tower with crown and spire/dome, base on y 0 at (x, z); scale.y to grow it. */\nexport function glassTower(mats: THREE.MeshStandardMaterial[], w: number, h: number, d: number, k: number, x: number, z: number): THREE.Group;\n/** Ring of cheap far towers (no shadows) on the horizon. */\nexport function farSkyline(o?: { seed?: number; count?: number; x?: number; width?: number; zNear?: number; zFar?: number; groundY?: number }): THREE.Group;\n```\n\n## Examples (imitate these)\nEvery hero builder returns { root, update(t) }: add root to the scene once, call update(t) every render. Read the file's header comment: it says WHAT TO COPY.\n- examples/ReclamationScene.tsx: THE LAND RECLAMATION SCENE written ONLY with the kit (a second pattern to imitate, next to TunnelScene).\n    export const ReclamationScene: React.FC<{ resolver: ModelResolver; info?: (id: string) => ModelInfo | undefined; finish?: \"full\" | \"fast\" | \"off\" }>\n- examples/TunnelScene.tsx: THE WHOLE TUNNEL SCENE (the approved proof) written ONLY with the kit: this is the file a model-written scene.tsx should imitate.\n    export const TunnelScene: React.FC<{ resolver: ModelResolver; info?: (id: string) => ModelInfo | undefined; finish?: \"full\" | \"fast\" | \"off\" }>\n- examples/boats.ts: Boats that float: each rests on the water level (never above or below it) and bobs a little. Used by both examples.\n    export function buildBoats(models: Models, specs: readonly BoatSpec[], seaY: number): Boats\n- examples/dims.ts: Shared measurements of the tunnel example (metres). COPY THE IDEA: one place for the numbers every part agrees on, so the machine,\n- examples/lining.ts: HERO EXAMPLE 2: the finished tunnel behind the machine: concrete lining rings (instanced), grout, track bed, sleepers, rails and\n    export function buildTunnel(): Lining\n- examples/reclamation.ts: HERO EXAMPLE 6: Dubai-style land reclamation. A ring wall of rock is built in the sea, a ship pours sand inside it (\"rainbowing\"),\n    export function buildReclamation(models: Models): Reclamation\n- examples/station.ts: HERO EXAMPLE 4: the underground station: slabs, platform with a safety line, columns, glowing lamp panels, signs, and a few catalogue\n    export function buildStation(models: Models): Station\n- examples/street.ts: HERO EXAMPLE 5: the street above the tunnel: road, sidewalks, towers and houses, trees, lamps, benches, walking people, cars,\n    export function buildStreet(models: Models): Street\n- examples/tbm.ts: HERO EXAMPLE 1: a tunnel boring machine, cut in half so you see inside. Not magic: boxes, cylinders, ring sectors and a few loops.\n    export function buildMachine(): Machine\n- examples/train.ts: HERO EXAMPLE 3: a metro train built from rounded boxes, window strips and bogies; it glides into the station.\n    export function buildTrain(o: TrainOptions = {}): Train\n";
export const S3K_EXAMPLE_A: string = "// EXAMPLE A (catalogue models): a crane lifts a container onto a ship. COPY: a world that reaches the horizon (quay + sea), models through\n// useModels, every object placed with rest(), motion as a pure function of t, a camera glide through three framed shots.\nimport React, { useMemo } from \"react\";\nimport { CameraRig, Finish, Hero, World, glideTimes, lerp, ramp, rest, shadowize, smooth, useModels, useT } from \"s3k\";\nimport type { SceneProps } from \"s3k\";\n\nconst CRANE = \"pp_crane_17ab\", BOX = \"pp_shipping_container_dqxr\", SHIP = \"pp_sail_ship_cizo\";\nconst FOCUS = { min: [-30, -3, -34] as [number, number, number], max: [30, 28, 12] as [number, number, number] };\nconst SEA_Y = -1.2;\n\nexport default function Scene({ resolver, durationS }: SceneProps) {\n  const models = useModels([CRANE, BOX, SHIP], resolver);\n  const t = useT();\n  const parts = useMemo(() => {\n    if (!models) return null;\n    const crane = shadowize(models.get(CRANE, { size: 26 }));\n    crane.position.set(-6, 0, -2);\n    const ship = shadowize(models.get(SHIP, { size: 34 }));\n    ship.position.set(8, 0, -16);\n    ship.rotation.y = Math.PI / 2;\n    rest(ship, SEA_Y + 0.4);\n    const box = shadowize(models.get(BOX, { size: 8 }));\n    return { crane, ship, box };\n  }, [models]);\n  const shots = useMemo(() => {\n    const [t0 = 0, t1 = 1, t2 = 2] = glideTimes(3, durationS);\n    return [\n      { t: t0, frame: { box: { min: [-14, 0, -6] as [number, number, number], max: [4, 26, 6] as [number, number, number] }, yawDeg: 24, pitchDeg: 10 } },\n      { t: t1, frame: { box: { min: [-14, 0, -20] as [number, number, number], max: [18, 16, 6] as [number, number, number] }, yawDeg: -18, pitchDeg: 14 } },\n      { t: t2, frame: { box: { min: [-2, -2, -22] as [number, number, number], max: [20, 14, -10] as [number, number, number] }, yawDeg: 12, pitchDeg: 18 } },\n    ];\n  }, [durationS]);\n  if (!parts) return null;\n  // The container travels from the quay (x -6, z 3) up, across and down onto the ship deck (x 8, z -16).\n  const up = smooth(ramp(t, 0.15 * durationS, 0.4 * durationS)), over = smooth(ramp(t, 0.4 * durationS, 0.7 * durationS)), down = smooth(ramp(t, 0.7 * durationS, 0.92 * durationS));\n  parts.box.position.set(lerp(-6, 8, over), lerp(0.2, 9, up) - 5.5 * down, lerp(3, -16, over));\n  return (\n    <>\n      <World focus={FOCUS} preset=\"clear\" ground={{ y: 0, kind: \"pave\", zMin: -4 }} sea={{ y: SEA_Y, zMax: -4 }} />\n      <Hero><primitive object={parts.crane} /></Hero>\n      <primitive object={parts.ship} />\n      <primitive object={parts.box} />\n      <CameraRig shots={shots} floor={2} />\n      <Finish />\n    </>\n  );\n}\n";
export const S3K_EXAMPLE_B: string = "// EXAMPLE B (no models): a tower rises row by row from a plaza, with dust. COPY: three.js geometry only from the allowed list, one InstancedMesh\n// for hundreds of bricks (one draw call), particles with makeParticles, seeded randomness (rnd), a loop with a constant bound, a camera glide.\nimport React, { useMemo } from \"react\";\nimport * as THREE from \"three\";\nimport { CameraRig, Finish, Hero, World, glideTimes, instance, lerp, makeParticles, placeSlots, ramp, rnd, smooth, std, useT } from \"s3k\";\nimport type { SceneProps } from \"s3k\";\n\nconst ROWS = 24, PER_ROW = 8, BRICK = { w: 1.2, h: 0.6, d: 1.2 };\nconst FOCUS = { min: [-14, 0, -14] as [number, number, number], max: [14, 18, 14] as [number, number, number] };\n\nexport default function Scene({ durationS }: SceneProps) {\n  const t = useT();\n  const parts = useMemo(() => {\n    const random = rnd(7);\n    const slots = [] as { x: number; y: number; z: number; ry: number }[];\n    for (let r = 0; r < ROWS; r++) {\n      for (let k = 0; k < PER_ROW; k++) {\n        const a = (k / PER_ROW) * Math.PI * 2 + (r % 2) * 0.2;\n        slots.push({ x: Math.cos(a) * 3.4, y: BRICK.h / 2 + r * BRICK.h, z: Math.sin(a) * 3.4, ry: -a + (random() - 0.5) * 0.04 });\n      }\n    }\n    const mat = std(\"#c9a27a\", { roughness: 0.8 });\n    const bricks = instance(new THREE.BoxGeometry(BRICK.w, BRICK.h, BRICK.d), mat, slots, { tint: (i) => (i % 3 === 0 ? \"#b98a62\" : \"#d8b48c\") });\n    const dust = makeParticles({ count: 220, seed: 3, size: 1.4, emit: (s, ph, time, out) => { out[0] = Math.cos(s.a) * (3 + s.r * 3); out[1] = 0.3 + ph * 6; out[2] = Math.sin(s.a) * (3 + s.r * 3); } });\n    return { slots, bricks, dust };\n  }, []);\n  // Rows appear one by one: row r is built between 10% and 85% of the film.\n  const built = ramp(t, 0.1 * durationS, 0.85 * durationS) * ROWS;\n  const shown = parts.slots.map((s) => ({ ...s, s: smooth(Math.min(1, Math.max(0, built - s.y / BRICK.h + 0.5))) })).map((s) => ({ ...s, y: lerp(s.y - 1, s.y, s.s), s: Math.max(0.001, s.s) }));\n  placeSlots(parts.bricks, shown);\n  parts.dust.update(t);\n  const shots = useMemo(() => {\n    const [t0 = 0, t1 = 1, t2 = 2] = glideTimes(3, durationS);\n    return [\n      { t: t0, frame: { box: { min: [-5, 0, -5] as [number, number, number], max: [5, 4, 5] as [number, number, number] }, yawDeg: 30, pitchDeg: 16 } },\n      { t: t1, frame: { box: { min: [-5, 0, -5] as [number, number, number], max: [5, 10, 5] as [number, number, number] }, yawDeg: -20, pitchDeg: 12 } },\n      { t: t2, frame: { box: { min: [-5, 0, -5] as [number, number, number], max: [5, 15, 5] as [number, number, number] }, yawDeg: 10, pitchDeg: 8 } },\n    ];\n  }, [durationS]);\n  return (\n    <>\n      <World focus={FOCUS} preset=\"haze\" ground={{ y: 0, kind: \"pave\" }} sea={false} />\n      <Hero><primitive object={parts.bricks} /></Hero>\n      <primitive object={parts.dust.points} />\n      <CameraRig shots={shots} floor={1.5} />\n      <Finish />\n    </>\n  );\n}\n";
export const S3K_EXAMPLE_C: string = "// EXAMPLE C (a machine, \"how it works\"): a lengthwise CUTAWAY of an engine. The casing is a half pipe, so you look inside and see four\n// separate STAGES in a row (fan, compressor, combustor, turbine), air particles that flow through them and change colour, and a camera that\n// follows the process stage by stage. COPY: a half-open casing (CylinderGeometry thetaLength), one InstancedMesh of blades per stage,\n// stage lights and glow materials, particles with makeParticles, a camera shot per stage from glideTimes, spinning blades from t.\nimport React, { useMemo } from \"react\";\nimport * as THREE from \"three\";\nimport { CameraRig, Finish, Hero, World, glideTimes, glow, instance, makeParticles, placeSlots, std, useT } from \"s3k\";\nimport type { SceneProps } from \"s3k\";\n\nconst LEN = 12, R = 2.2, CENTRE_Y = 2.6; // engine runs along x from -6 to 6, resting on a stand\nconst STAGE_X = [-4.5, -1.5, 1.5, 4.5]; // fan, compressor, combustor, turbine\nconst FOCUS = { min: [-8, 0, -4] as [number, number, number], max: [8, 6, 4] as [number, number, number] };\ntype Slot = { x: number; y: number; z: number; rx?: number; ry?: number; rz?: number };\n\nexport default function Scene({ durationS }: SceneProps) {\n  const t = useT();\n  const parts = useMemo(() => {\n    // The casing: a half pipe (open towards the viewer, +z) so the inside is visible. thetaLength = half a circle.\n    const casing = new THREE.Mesh(\n      new THREE.CylinderGeometry(R, R, LEN, 48, 1, true, Math.PI, Math.PI),\n      std(\"#8f98a3\", { roughness: 0.45, metalness: 0.7, side: THREE.DoubleSide }),\n    );\n    casing.rotation.z = Math.PI / 2;\n    casing.position.set(0, CENTRE_Y, 0);\n    // Four glowing stage rings so each stage is clearly separate and has its own colour.\n    const ringColours = [\"#7fd1ff\", \"#5aa8ff\", \"#ff9a3c\", \"#ff5a2a\"];\n    const rings: THREE.Mesh[] = [];\n    for (let k = 0; k < 4; k++) {\n      const m = new THREE.Mesh(new THREE.TorusGeometry(R * 0.98, 0.06, 12, 48, Math.PI), glow(ringColours[k] ?? \"#ffffff\", 1.4));\n      m.rotation.y = Math.PI / 2;\n      m.position.set((STAGE_X[k] ?? 0) - 1.2, CENTRE_Y, 0);\n      rings.push(m);\n    }\n    // The centre shaft that all blades sit on.\n    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, LEN - 0.6, 20), std(\"#b9c0c8\", { roughness: 0.3, metalness: 0.9 }));\n    shaft.rotation.z = Math.PI / 2;\n    shaft.position.set(0, CENTRE_Y, 0);\n    // One InstancedMesh of blades per stage (a ring of 14 flat blades each). Each stage has its own size and colour.\n    const BLADES = 14;\n    const bladeGeo = new THREE.BoxGeometry(0.08, 1, 0.34);\n    const makeBlades = (x: number, len: number, colour: string) => {\n      const slots: Slot[] = [];\n      for (let i = 0; i < BLADES; i++) {\n        const a = (i / BLADES) * Math.PI * 2;\n        slots.push({ x, y: CENTRE_Y + Math.cos(a) * len * 0.5, z: Math.sin(a) * len * 0.5, rx: a });\n      }\n      return { slots, mesh: instance(bladeGeo, std(colour, { roughness: 0.35, metalness: 0.8 }), slots), x, len };\n    };\n    const stages = [makeBlades(STAGE_X[0] ?? 0, 2.0, \"#cfe9ff\"), makeBlades(STAGE_X[1] ?? 0, 1.6, \"#9cc4ee\"), makeBlades(STAGE_X[2] ?? 0, 1.0, \"#ffb36b\"), makeBlades(STAGE_X[3] ?? 0, 1.5, \"#e6552b\")];\n    // Air: particles enter at the left, are squeezed through the stages and leave hot at the right. Colour changes by stage via position.\n    const air = makeParticles({\n      count: 700, seed: 5, size: 0.22, color: \"#bfe6ff\", opacity: 0.9,\n      emit: (s, ph, time, out) => {\n        const x = -LEN / 2 + ph * LEN;\n        const squeeze = 1 - 0.55 * Math.min(1, Math.max(0, (x + 4) / 5)); // the channel narrows towards the combustor\n        const swirl = s.a + time * 3 + ph * 8;\n        out[0] = x;\n        out[1] = CENTRE_Y + Math.cos(swirl) * R * 0.7 * squeeze * s.r;\n        out[2] = Math.sin(swirl) * R * 0.7 * squeeze * s.r;\n      },\n    });\n    // The fire: bright particles inside the combustor (stage 3) only.\n    const fire = makeParticles({\n      count: 260, seed: 9, size: 0.45, color: \"#ff7a1a\", opacity: 1,\n      emit: (s, ph, time, out) => {\n        out[0] = STAGE_X[2]! - 1.1 + ph * 2.4;\n        out[1] = CENTRE_Y + (s.v - 0.5) * 0.6 + Math.cos(s.a + time * 5) * 0.5 * s.r;\n        out[2] = Math.sin(s.a + time * 5) * 0.5 * s.r;\n      },\n    });\n    // The stand under the engine so nothing floats.\n    const stand = new THREE.Mesh(new THREE.BoxGeometry(LEN - 2, 0.5, 1.2), std(\"#3b4048\", { roughness: 0.8 }));\n    stand.position.set(0, 0.25, 0);\n    return { casing, rings, shaft, stages, air, fire, stand };\n  }, []);\n  // Every blade ring spins; the fan and compressor spin one way, the turbine the other, all as a pure function of t.\n  parts.stages.forEach((st, k) => {\n    const spin = t * (k === 3 ? -9 : 7);\n    const slots = st.slots.map((s, i) => {\n      const a = (i / st.slots.length) * Math.PI * 2 + spin;\n      return { ...s, y: CENTRE_Y + Math.cos(a) * st.len * 0.5, z: Math.sin(a) * st.len * 0.5, rx: a };\n    });\n    placeSlots(st.mesh, slots);\n  });\n  parts.air.update(t);\n  parts.fire.update(t);\n  // One camera shot per stage, in order: the whole engine, then fan, compressor, combustor, turbine. The camera glides along the engine.\n  const shots = useMemo(() => {\n    const times = glideTimes(5, durationS);\n    const box = (x0: number, x1: number) => ({ min: [x0, 0.8, -2.2] as [number, number, number], max: [x1, 4.6, 2.2] as [number, number, number] });\n    return [\n      { t: times[0] ?? 0, frame: { box: box(-6, 6), yawDeg: 20, pitchDeg: 14 } },\n      { t: times[1] ?? 1, frame: { box: box(-6, -3), yawDeg: 28, pitchDeg: 10 } },\n      { t: times[2] ?? 2, frame: { box: box(-3, 0), yawDeg: 22, pitchDeg: 10 } },\n      { t: times[3] ?? 3, frame: { box: box(0, 3), yawDeg: 16, pitchDeg: 10 } },\n      { t: times[4] ?? 4, frame: { box: box(3, 6), yawDeg: 10, pitchDeg: 10 } },\n    ];\n  }, [durationS]);\n  return (\n    <>\n      <World focus={FOCUS} preset=\"clear\" ground={{ y: 0, kind: \"pave\" }} sea={false} />\n      <Hero>\n        <group>\n          <primitive object={parts.casing} />\n          <primitive object={parts.shaft} />\n          {parts.rings.map((r, i) => (\n            <primitive key={i} object={r} />\n          ))}\n          {parts.stages.map((s, i) => (\n            <primitive key={i} object={s.mesh} />\n          ))}\n        </group>\n      </Hero>\n      <primitive object={parts.stand} />\n      <primitive object={parts.air.points} />\n      <primitive object={parts.fire.points} />\n      <CameraRig shots={shots} floor={0.8} />\n      <Finish />\n    </>\n  );\n}\n";
export const S3K_EXAMPLE_D: string = "// EXAMPLE D (an idea, no models): a doubly linked list. COPY for any abstract topic (data structures, algorithms, networks, how data flows):\n// big simple parts on the \"studio\" backdrop, laid out to fill the TALL frame (a staircase, not a long row), arrow() for every link so the\n// direction reads, label() tags that name the parts (head, next, prev, null, values), one idea per beat in time order, and shots that\n// change size and angle between beats while the whole hero stays in the frame.\nimport React, { useMemo } from \"react\";\nimport * as THREE from \"three\";\nimport { CameraRig, Finish, Hero, World, arrow, box, glideTimes, glow, label, ramp, smooth, std, useT } from \"s3k\";\nimport type { SceneProps } from \"s3k\";\n\nconst N = 4, W = 3.2, H = 1.8, D = 1.4, STEP_X = 1.6, STEP_Y = 3.2, BOTTOM = 1.6;\nconst VALUES = [\"12\", \"7\", \"31\", \"5\"];\nconst nodeAt = (i: number) => new THREE.Vector3(-((N - 1) * STEP_X) / 2 + i * STEP_X, BOTTOM + (N - 1 - i) * STEP_Y, 0);\nconst FOCUS = { min: [-6, 0, -3] as [number, number, number], max: [6, 13.5, 3] as [number, number, number] };\nconst HERO_BOX = { min: [-5, 0.4, -0.8] as [number, number, number], max: [5.6, 12.6, 0.8] as [number, number, number] }; // includes the tags\n\nexport default function Scene({ durationS }: SceneProps) {\n  const t = useT();\n  const parts = useMemo(() => {\n    const hero = new THREE.Group(), tags = new THREE.Group();\n    const body = std(\"#e9eef8\", { roughness: 0.45 }), nextBox = std(\"#2ec5d3\", { roughness: 0.4 }), prevBox = std(\"#f2994a\", { roughness: 0.4 });\n    const nextMat = glow(\"#36e0f0\", 2.2), prevMat = glow(\"#ffa64d\", 2.2);\n    const nodes: THREE.Group[] = [], values: THREE.Sprite[] = [];\n    for (let i = 0; i < N; i++) {\n      const g = new THREE.Group();\n      g.position.copy(nodeAt(i));\n      box(0.8, H, D, prevBox, -W / 2 + 0.4, 0, 0, g); // prev slot (left)\n      box(W - 1.6, H, D, body, 0, 0, 0, g); // data slot (middle)\n      box(0.8, H, D, nextBox, W / 2 - 0.4, 0, 0, g); // next slot (right)\n      hero.add(g);\n      nodes.push(g);\n      const v = label(VALUES[i] ?? \"\", { size: 0.9 });\n      v.position.copy(nodeAt(i)).add(new THREE.Vector3(0, 0, D / 2 + 0.05));\n      tags.add(v);\n      values.push(v);\n    }\n    // A link grows from its start: the arrow is built at the origin of a pivot that sits on the start point, then the pivot is scaled.\n    const link = (a: THREE.Vector3, b: THREE.Vector3, mat: THREE.Material) => {\n      const pivot = new THREE.Group();\n      pivot.position.copy(a);\n      arrow(new THREE.Vector3(0, 0, 0), b.clone().sub(a), 0.13, mat, pivot);\n      hero.add(pivot);\n      return pivot;\n    };\n    const next: THREE.Group[] = [], prev: THREE.Group[] = [];\n    for (let i = 0; i < N - 1; i++) {\n      const a = nodeAt(i), b = nodeAt(i + 1);\n      next.push(link(new THREE.Vector3(a.x + W / 2 - 0.4, a.y - H / 2, 0.3), new THREE.Vector3(b.x + W / 2 - 0.4, b.y + H / 2 + 0.05, 0.3), nextMat));\n      prev.push(link(new THREE.Vector3(b.x - W / 2 + 0.4, b.y + H / 2, -0.3), new THREE.Vector3(a.x - W / 2 + 0.4, a.y - H / 2 - 0.05, -0.3), prevMat));\n    }\n    const last = nodeAt(N - 1);\n    const nullLink = link(new THREE.Vector3(last.x + W / 2, last.y, 0), new THREE.Vector3(last.x + W / 2 + 0.9, last.y, 0), nextMat);\n    const tag = (text: string, at: THREE.Vector3, size = 0.95) => { const s = label(text, { size }); s.position.copy(at); tags.add(s); return s; };\n    const first = nodeAt(0);\n    const head = tag(\"head\", new THREE.Vector3(first.x - 1.3, first.y + H / 2 + 0.8, 0));\n    const nul = tag(\"null\", new THREE.Vector3(last.x + W / 2 + 0.6, last.y - H / 2 - 0.7, 0));\n    const nextTag = tag(\"next\", new THREE.Vector3(nodeAt(1).x + W / 2 + 1.0, nodeAt(1).y + H / 2 + 0.7, 0));\n    const prevTag = tag(\"prev\", new THREE.Vector3(nodeAt(1).x - W / 2 - 1.0, nodeAt(1).y + H / 2 + 0.7, 0));\n    const marker = new THREE.Mesh(new THREE.SphereGeometry(0.35, 24, 16), glow(\"#fff6c2\", 3));\n    hero.add(marker);\n    return { hero, tags, nodes, values, next, prev, nullLink, head, nul, nextTag, prevTag, marker };\n  }, []);\n\n  // One idea per stretch of the film (fractions of the length, so it fits any narration).\n  const at = (f: number) => f * durationS;\n  parts.nodes.forEach((g, i) => g.scale.setScalar(Math.max(0.001, smooth(ramp(t, at(0.02 + i * 0.03), at(0.06 + i * 0.03))))));\n  parts.values.forEach((v, i) => { v.visible = t > at(0.06 + i * 0.03); });\n  parts.head.visible = t > at(0.12);\n  parts.next.forEach((p, i) => p.scale.setScalar(Math.max(0.001, smooth(ramp(t, at(0.16 + i * 0.05), at(0.21 + i * 0.05))))));\n  parts.nextTag.visible = t > at(0.2);\n  parts.nullLink.scale.setScalar(Math.max(0.001, smooth(ramp(t, at(0.31), at(0.34)))));\n  parts.nul.visible = t > at(0.34);\n  parts.prev.forEach((p, i) => p.scale.setScalar(Math.max(0.001, smooth(ramp(t, at(0.52 + i * 0.05), at(0.57 + i * 0.05))))));\n  parts.prevTag.visible = t > at(0.56);\n  // The marker walks down the next links (0.36..0.5), then back up the prev links (0.7..0.84).\n  const down = ramp(t, at(0.36), at(0.5)) * (N - 1), up = ramp(t, at(0.7), at(0.84)) * (N - 1);\n  const pos = t < at(0.7) ? down : N - 1 - up;\n  const k = Math.min(N - 2, Math.floor(pos)), u = smooth(pos - k);\n  const a = nodeAt(k), b = nodeAt(k + 1);\n  parts.marker.position.set(a.x + (b.x - a.x) * u, a.y + (b.y - a.y) * u + H / 2 + 0.45, 0);\n  parts.marker.visible = t > at(0.36);\n\n  const shots = useMemo(() => {\n    const [t0 = 0, t1 = 1, t2 = 2, t3 = 3] = glideTimes(4, durationS);\n    return [\n      { t: t0, frame: { box: HERO_BOX, yawDeg: 0, pitchDeg: 6 } },\n      { t: t1, frame: { box: HERO_BOX, yawDeg: 26, pitchDeg: 10, distanceMul: 1.3 } },\n      { t: t2, frame: { box: HERO_BOX, yawDeg: -24, pitchDeg: 4 } },\n      { t: t3, frame: { box: HERO_BOX, yawDeg: 8, pitchDeg: 12, distanceMul: 1.45 } },\n    ];\n  }, [durationS]);\n  return (\n    <>\n      <World focus={FOCUS} preset=\"studio\" ground={{ y: 0, kind: \"plain\", color: \"#141b2e\" }} sea={false} />\n      <Hero><primitive object={parts.hero} /></Hero>\n      <primitive object={parts.tags} />\n      <CameraRig shots={shots} floor={1.2} />\n      <Finish />\n    </>\n  );\n}\n";
